def chain_of_chain(chain):
    # Step 1: Identify the first and last tokens in the chain
    first, last = chain[0], chain[-1]
    # Step 2: Find the token that precedes the first token
    for token in chain[1:]:
        if token == first:
            break
    # Step 3: Find the token that follows the last token
    for token in chain[1:]:
        if token == last:
            break
    # Step 4: Construct the chain
    return chain[0] + chain[1:1]
